149	        return out;
150	    }
151	
152	    // ---- 3. ABI 版本校验：布局不符时宁可不可用，也不能拿错位数据当结论 ----
153	    if (local.hdr.abi_version != WEAKNET_KMOD_ABI_VERSION) {
154	        out.reason = "abi_mismatch";
155	        return out;
156	    }
157	
158	    if (local.hdr.nr_cpus == 0) {
