168	        Impl::CpuTimes t;
169	        t.cpu_id = c.cpu_id;
170	        t.online = (c.online != 0);
171	        t.valid = (c.valid != 0);
172	        // 与内核 ABI 头同口径：guest 已含在 user 内，不重复计入 busy
173	        t.busy = c.user + c.nice + c.system + c.irq + c.softirq + c.steal;
174	        t.total = t.busy + c.idle + c.iowait;
175	        cur.push_back(t);
176	    }
