178	    uint32_t online = 0;
179	    for (const auto& t : cur) {
180	        if (t.online) ++online;
181	    }
182	    out.online_cpus = online;
183	
184	    if (!impl_->have_prev) {
185	        impl_->prev = std::move(cur);
186	        impl_->have_prev = true;
