/**
 * @file test_frame_source_gtest.cpp
 * @brief 帧源接口与合成源的契约真值表
 *
 * 这份测试守的是「L2/L3 层的语义边界」，而不是「实现恰好算出什么数」。
 * 每条断言背后都有一个会导致归因误判的失效模式：
 *
 *   1. 未启动时不得返回"健康"的全零统计 —— 缺数据伪装成好数据
 *   2. 乱序不得计入丢帧 —— 驱动行为被误判成网络故障
 *   3. 一次断流与多次小丢帧必须可区分 —— "卡住" 与 "断续" 的用户感知不同
 *   4. snapshotAndReset 必须真清零 —— 否则丢帧率被重复计算
 *   5. describe() 必须标明来源 —— 合成数据不能被当成真机证据
 */

#include <gtest/gtest.h>

#include <chrono>
#include <set>
#include <string>

#include "frame_source.hpp"

using namespace weaknet;

// ---------------------------------------------------------------------------
// 1. 生命周期与缺数据语义
// ---------------------------------------------------------------------------

TEST(FrameStats, DefaultConstructedIsInvalidNotHealthy) {
    // 这是整份文件最重要的一条断言。
    //
    // FrameStats 的默认值全是 0，而 frameLossRatio() 对 expected==0 返回 0.0。
    // 也就是说「从未采样」看起来和「完美运行」完全一样。只有 valid() 能区分。
    // 任何下游代码若不先检查 valid()，就会把「不知道」当成「很好」。
    FrameStats s;

    EXPECT_FALSE(s.valid());
    EXPECT_EQ(s.frames_expected, 0u);
    EXPECT_DOUBLE_EQ(s.frameLossRatio(), 0.0);
    // 显式钉死这个陷阱的存在，防止有人"顺手"删掉 valid()
    EXPECT_EQ(s.framesLost(), 0u);
}

TEST(SyntheticFrameSource, SnapshotBeforeStartIsInvalid) {
    SyntheticFrameSource src(SyntheticPattern::HEALTHY, 30, 1000);

    auto s = src.snapshotAndReset();

    EXPECT_FALSE(s.valid()) << "未 start 就返回有效统计 = 伪造数据";
    EXPECT_EQ(s.frames_expected, 0u);
}

TEST(SyntheticFrameSource, StartThenStopIsIdempotent) {
    SyntheticFrameSource src(SyntheticPattern::HEALTHY, 30, 1000);

    // 未 start 直接 stop 不得崩溃（接口契约要求可重入）
    src.stop();

    ASSERT_TRUE(src.start());
    auto a = src.snapshotAndReset();
    EXPECT_TRUE(a.valid());

    src.stop();
    src.stop();   // 重复 stop

    // stop 之后再取，必须回到 invalid
    auto b = src.snapshotAndReset();
    EXPECT_FALSE(b.valid());
}

TEST(SyntheticFrameSource, RestartResetsTimeline) {
    SyntheticFrameSource src(SyntheticPattern::PERIODIC_LOSS, 30, 1000);

    src.start();
    for (int i = 0; i < 5; ++i) src.snapshotAndReset();
    EXPECT_EQ(src.windowCount(), 5u);

    src.stop();
    src.start();
    EXPECT_EQ(src.windowCount(), 0u) << "重启必须重置窗口计数，否则模式相位错乱";
    EXPECT_EQ(src.nextSeq(), 0u);
}

// ---------------------------------------------------------------------------
// 2. HEALTHY：无丢帧、无抖动
// ---------------------------------------------------------------------------

TEST(SyntheticFrameSource, HealthyHasNoLossAndNoJitter) {
    SyntheticFrameSource src(SyntheticPattern::HEALTHY, 30, 1000);

    ASSERT_TRUE(src.start());
    auto s = src.snapshotAndReset();

    EXPECT_TRUE(s.valid());
    EXPECT_EQ(s.frames_expected, 30u) << "30fps × 1000ms 应为 30 帧";
    EXPECT_EQ(s.frames_received, 30u);
    EXPECT_EQ(s.seq_gap_count, 0u);
    EXPECT_EQ(s.frames_corrupt, 0u);
    EXPECT_DOUBLE_EQ(s.frameLossRatio(), 0.0);

    // 30fps → 每帧 33.33ms，取整后最大间隔也是 33
    EXPECT_EQ(s.max_gap_ms, 33u);
    EXPECT_LE(s.p95_gap_ms, s.max_gap_ms);
    EXPECT_GT(s.bytes_received, 0u);
}

TEST(SyntheticFrameSource, HealthyIsDeterministic) {
    // 同一组参数必须得到同一份结果（不含时间戳）。
    // 不 sleep 的设计价值就在这里：CI 上不会因调度抖动而偶发失败。
    SyntheticFrameSource a(SyntheticPattern::HEALTHY, 30, 1000);
    SyntheticFrameSource b(SyntheticPattern::HEALTHY, 30, 1000);

    a.start();
    b.start();

    for (int i = 0; i < 3; ++i) {
        auto sa = a.snapshotAndReset();
        auto sb = b.snapshotAndReset();
        EXPECT_EQ(sa.frames_expected, sb.frames_expected) << "round " << i;
        EXPECT_EQ(sa.frames_received, sb.frames_received) << "round " << i;
        EXPECT_EQ(sa.seq_gap_count, sb.seq_gap_count) << "round " << i;
        EXPECT_EQ(sa.max_gap_ms, sb.max_gap_ms) << "round " << i;
        EXPECT_EQ(sa.p95_gap_ms, sb.p95_gap_ms) << "round " << i;
    }
}

// ---------------------------------------------------------------------------
// 3. PERIODIC_LOSS：少量但频繁
// ---------------------------------------------------------------------------

TEST(SyntheticFrameSource, PeriodicLossReportsEveryGapEvent) {
    SyntheticFrameSource src(SyntheticPattern::PERIODIC_LOSS, 30, 1000);

    ASSERT_TRUE(src.start());
    auto s = src.snapshotAndReset();

    EXPECT_TRUE(s.valid());
    // 30 帧里每 30 帧丢 2 帧 → 本窗口恰好 1 次周期命中，丢 2 帧
    EXPECT_EQ(s.seq_gap_count, 2u) << "2 帧各算一次序号跳变";
    EXPECT_EQ(s.frames_received, 28u);
    EXPECT_EQ(s.frames_expected, 30u);
    EXPECT_DOUBLE_EQ(s.frameLossRatio(), 2.0 / 30.0);
}

TEST(SyntheticFrameSource, PeriodicLossLossRateIsStableAcrossWindows) {
    // 周期性丢帧的定义就是"每窗口都有、比例稳定"，
    // 若某窗口丢 0 帧说明相位算错了。
    SyntheticFrameSource src(SyntheticPattern::PERIODIC_LOSS, 30, 1000);
    src.start();

    std::set<uint64_t> received_values;
    for (int i = 0; i < 10; ++i) {
        auto s = src.snapshotAndReset();
        received_values.insert(s.frames_received);
        EXPECT_LT(s.frames_received, s.frames_expected) << "round " << i << " 不该有完好窗口";
    }
    // 相位随窗口推进，收到的帧数允许有 1~2 帧波动，但收敛在 28 附近
    EXPECT_LE(received_values.size(), 3u);
}

// ---------------------------------------------------------------------------
// 4. BURST_LOSS：一次断流 vs 多次小丢帧
// ---------------------------------------------------------------------------

TEST(SyntheticFrameSource, BurstLossIsOneEventNotMany) {
    // 关键语义：一次丢 9 帧记 1 次事件，而不是 9 次。
    // 这决定了归因层能否区分"画面卡住了"和"画面在断续"。
    SyntheticFrameSource src(SyntheticPattern::BURST_LOSS, 30, 1000);
    src.start();

    auto even = src.snapshotAndReset();   // 窗口 0：正常
    auto odd  = src.snapshotAndReset();   // 窗口 1：突发丢帧

    EXPECT_EQ(even.seq_gap_count, 0u);
    EXPECT_EQ(even.frames_received, even.frames_expected);

    EXPECT_LT(odd.frames_received, odd.frames_expected);
    EXPECT_EQ(odd.seq_gap_count, 1u) << "连续丢一段只算 1 次中断事件";
    EXPECT_EQ(odd.frames_received, 21u) << "30 帧丢 30% 应剩 21 帧";
}

TEST(SyntheticFrameSource, BurstLossProducesLongGap) {
    SyntheticFrameSource src(SyntheticPattern::BURST_LOSS, 30, 1000);
    src.start();
    src.snapshotAndReset();   // 跳过正常窗口

    auto burst = src.snapshotAndReset();

    // 断流窗口必须出现一个显著拉长的间隔（远大于 33ms 的标称间隔）
    EXPECT_GT(burst.max_gap_ms, 100u)
        << "突发断流必须体现在 max_gap_ms 上，否则与周期丢帧无法区分";
}

TEST(SyntheticFrameSource, BurstLossAlternates) {
    SyntheticFrameSource src(SyntheticPattern::BURST_LOSS, 30, 1000);
    src.start();

    for (int i = 0; i < 6; ++i) {
        auto s = src.snapshotAndReset();
        if (i % 2 == 0) {
            EXPECT_EQ(s.seq_gap_count, 0u) << "窗口 " << i << " 应为正常";
        } else {
            EXPECT_EQ(s.seq_gap_count, 1u) << "窗口 " << i << " 应为一次突发";
        }
    }
}

// ---------------------------------------------------------------------------
// 5. REORDERED：乱序不是丢帧（最容易写错的一条）
// ---------------------------------------------------------------------------

TEST(SyntheticFrameSource, ReorderedIsNotCountedAsLoss) {
    // 这条断言守住归因正确性：
    // 驱动重排是本地行为，若计入丢帧，归因层会把"驱动问题"报成"网络故障"。
    SyntheticFrameSource src(SyntheticPattern::REORDERED, 30, 1000);

    ASSERT_TRUE(src.start());
    auto s = src.snapshotAndReset();

    EXPECT_TRUE(s.valid());
    EXPECT_EQ(s.seq_gap_count, 0u) << "乱序不得计入丢帧事件";
    EXPECT_EQ(s.frames_received, s.frames_expected) << "帧全都到了";
    EXPECT_DOUBLE_EQ(s.frameLossRatio(), 0.0);

    // 间隔也应正常：乱序是顺序问题，不是时间问题
    EXPECT_EQ(s.max_gap_ms, 33u);
}

TEST(SyntheticFrameSource, ReorderedDiffersFromPeriodicLoss) {
    // 反向确认两种模式真的有区别（防止实现里两个分支写成一样）
    SyntheticFrameSource reordered(SyntheticPattern::REORDERED, 30, 1000);
    SyntheticFrameSource periodic(SyntheticPattern::PERIODIC_LOSS, 30, 1000);

    reordered.start();
    periodic.start();

    auto a = reordered.snapshotAndReset();
    auto b = periodic.snapshotAndReset();

    EXPECT_EQ(a.seq_gap_count, 0u);
    EXPECT_GT(b.seq_gap_count, 0u);
    EXPECT_NE(a.describe(), b.describe());
}

// ---------------------------------------------------------------------------
// 6. snapshotAndReset 的「取走并清零」语义
// ---------------------------------------------------------------------------

TEST(SyntheticFrameSource, SnapshotAdvancesTimeline) {
    SyntheticFrameSource src(SyntheticPattern::HEALTHY, 30, 1000);
    src.start();

    EXPECT_EQ(src.windowCount(), 0u);
    EXPECT_EQ(src.nextSeq(), 0u);

    src.snapshotAndReset();
    EXPECT_EQ(src.windowCount(), 1u);
    EXPECT_EQ(src.nextSeq(), 30u);

    src.snapshotAndReset();
    EXPECT_EQ(src.windowCount(), 2u);
    EXPECT_EQ(src.nextSeq(), 60u);
}

TEST(SyntheticFrameSource, EachSnapshotCoversItsOwnWindowOnly) {
    // 若实现返回累计值而非增量，连续两次快照会把同一批帧算两遍，
    // 导致丢帧率虚高。这里用 BURST 的交替性来检测。
    SyntheticFrameSource src(SyntheticPattern::BURST_LOSS, 30, 1000);
    src.start();

    auto first = src.snapshotAndReset();
    auto second = src.snapshotAndReset();
    auto third = src.snapshotAndReset();

    // 每个窗口的 frames_expected 都应该是独立的 30，不累加
    EXPECT_EQ(first.frames_expected, 30u);
    EXPECT_EQ(second.frames_expected, 30u);
    EXPECT_EQ(third.frames_expected, 30u);

    // 交替模式：0 正常、1 突发、2 正常
    EXPECT_EQ(first.seq_gap_count, 0u);
    EXPECT_EQ(second.seq_gap_count, 1u);
    EXPECT_EQ(third.seq_gap_count, 0u);
}

// ---------------------------------------------------------------------------
// 7. describe()：evidence 溯源
// ---------------------------------------------------------------------------

TEST(SyntheticFrameSource, DescribeMarksItAsSynthetic) {
    // 前缀必须是 synthetic: —— 事后审证据时要能一眼区分
    // "真机观测" 与 "注入的测试数据"。这是本项目 evidence 纪律的一部分。
    SyntheticFrameSource src(SyntheticPattern::BURST_LOSS, 25, 500);

    const std::string d = src.describe();

    EXPECT_EQ(d.rfind("synthetic:", 0), 0) << "实际: " << d;
    EXPECT_NE(d.find("BURST_LOSS"), std::string::npos) << "实际: " << d;
    EXPECT_NE(d.find("25"), std::string::npos) << "应含帧率，实际: " << d;
    EXPECT_NE(d.find("500"), std::string::npos) << "应含窗口时长，实际: " << d;
}

TEST(SyntheticFrameSource, DescribeCoversAllPatterns) {
    struct Case { SyntheticPattern p; const char* name; };
    const Case cases[] = {
        {SyntheticPattern::HEALTHY,       "HEALTHY"},
        {SyntheticPattern::PERIODIC_LOSS, "PERIODIC_LOSS"},
        {SyntheticPattern::BURST_LOSS,    "BURST_LOSS"},
        {SyntheticPattern::REORDERED,     "REORDERED"},
    };

    for (const auto& c : cases) {
        SyntheticFrameSource src(c.p, 30, 1000);
        EXPECT_NE(src.describe().find(c.name), std::string::npos)
            << "pattern " << c.name << " 的描述缺失";
    }
}

// ---------------------------------------------------------------------------
// 8. 参数边界：非法输入不得崩溃或产生 NaN
// ---------------------------------------------------------------------------

TEST(SyntheticFrameSource, ZeroFpsDoesNotDivideByZero) {
    // 构造时 fps=0，实现内部钳到 30。若直接拿 0 做除数，
    // frame_interval_ms 会变成 inf，进而把 nominal_frames 转成 0 或 UB。
    SyntheticFrameSource src(SyntheticPattern::HEALTHY, 0, 1000);

    ASSERT_TRUE(src.start());
    auto s = src.snapshotAndReset();

    EXPECT_TRUE(s.valid());
    EXPECT_GT(s.frames_expected, 0u) << "不应因非法 fps 退化成 0 帧";
    EXPECT_FALSE(std::isnan(s.frameLossRatio()));
}

TEST(SyntheticFrameSource, ZeroWindowDoesNotProduceEmptyWindow) {
    SyntheticFrameSource src(SyntheticPattern::HEALTHY, 30, 0);

    ASSERT_TRUE(src.start());
    auto s = src.snapshotAndReset();

    EXPECT_TRUE(s.valid());
    EXPECT_GT(s.frames_expected, 0u) << "窗口时长为 0 时钳到 1000ms";
}

TEST(FrameStats, LossRatioIsClampedToZeroWhenReceivedExceedsExpected) {
    // 期望值配小了（如配置错误）时，framesLost() 不能返回负数，
    // 否则丢帧率会变成负值，下游阈值判断全部失效。
    FrameStats s;
    s.frames_expected = 10;
    s.frames_received = 15;

    EXPECT_EQ(s.framesLost(), 0u);
    EXPECT_DOUBLE_EQ(s.frameLossRatio(), 0.0);
}

TEST(FrameStats, ValidRequiresSampledAt) {
    FrameStats s;
    s.frames_expected = 100;
    s.frames_received = 100;
    // 数据都填好了但没时间戳 —— 仍然不算有效采样。
    // 时间戳是"这次采样真的发生过"的唯一凭证。
    EXPECT_FALSE(s.valid());

    s.sampled_at = std::chrono::steady_clock::now();
    EXPECT_TRUE(s.valid());
}

// ---------------------------------------------------------------------------
// 9. 多态性：IFrameSource 指针可承载两种实现
// ---------------------------------------------------------------------------

TEST(IFrameSource, UsableThroughBasePointer) {
    // 这条测试的存在意义是锁定接口设计目标：上层只依赖 IFrameSource，
    // 将来加 V4l2FrameSource 时不需要改动任何调用方代码。
    std::unique_ptr<IFrameSource> src =
        std::make_unique<SyntheticFrameSource>(SyntheticPattern::HEALTHY, 30, 1000);

    ASSERT_TRUE(src->start());
    auto s = src->snapshotAndReset();
    EXPECT_TRUE(s.valid());
    EXPECT_FALSE(src->describe().empty());
    src->stop();
}

/**
 * @file synthetic_frame_source.cpp
 * @brief 合成帧源实现：把「时间」当纯函数参数，不 sleep、不依赖真实时钟
 *
 * 设计要点（三个刻意的取舍）：
 *
 * 1. **不 sleep**：单测如果 sleep，CI 上会慢且不确定（调度抖动会让 P95 漂移）。
 *    这里每次 snapshotAndReset() 直接推进一个窗口并按模式算出本该发生的统计，
 *    同一组参数永远得到同一份结果。
 *
 * 2. **乱序 ≠ 丢帧**：REORDERED 模式下所有帧都到了，只是顺序错乱。
 *    实现里它只影响 bytes 与帧数，绝不增加 seq_gap_count。这条边界是
 *    归因正确性的前提——把驱动重排当成网络丢包，会让归因层误报链路故障。
 *
 * 3. **P95 用排序取位而非近似**：窗口内帧数在几百量级，全排序的成本可以
 *    忽略，而近似算法（如直方图分桶）会引入桶宽误差，让 1ms 级的抖动
 *    判定失真。宁可简单准确，也不做没必要的优化。
 */

#include "frame_source.hpp"

#include <algorithm>
#include <cmath>
#include <cstdlib>
#include <sstream>
#include <vector>

namespace weaknet {

namespace {

/// 合成帧的假定帧大小（未压缩的 NV12 近似值，仅用于让 bytes_received 非零）
constexpr uint64_t kSyntheticFrameBytes = 640u * 480u * 3u / 2u;

/**
 * @brief 计算 P95（最近秩法）
 *
 * 空容器返回 0。取 ceil(0.95 * n) - 1 下标，n=20 时取第 19 个（0-based 18），
 * 语义是「95% 的样本不超过该值」，与本项目其它 P95 用法一致。
 */
uint32_t percentile95(std::vector<uint32_t> values) {
    if (values.empty()) return 0;
    std::sort(values.begin(), values.end());
    const size_t idx = static_cast<size_t>(
        std::ceil(0.95 * static_cast<double>(values.size())) - 1.0);
    return values[std::min(idx, values.size() - 1)];
}

}  // namespace

struct SyntheticFrameSource::Impl {
    SyntheticPattern pattern;
    uint32_t fps;
    uint32_t window_ms;

    bool started = false;
    uint64_t window = 0;      ///< 已推进的窗口数
    uint64_t next_seq = 0;    ///< 下一个帧序号

    Impl(SyntheticPattern p, uint32_t f, uint32_t w)
        : pattern(p), fps(f ? f : 30), window_ms(w ? w : 1000) {}
};

SyntheticFrameSource::SyntheticFrameSource(SyntheticPattern pattern, uint32_t fps,
                                           uint32_t window_ms)
    : impl_(std::make_unique<Impl>(pattern, fps, window_ms)) {}

SyntheticFrameSource::~SyntheticFrameSource() = default;

bool SyntheticFrameSource::start() {
    impl_->started = true;
    impl_->window = 0;
    impl_->next_seq = 0;
    return true;
}

void SyntheticFrameSource::stop() {
    // 幂等：未 start 时调用不做事，也不改动计数
    impl_->started = false;
}

FrameStats SyntheticFrameSource::snapshotAndReset() {
    FrameStats out;

    // 未启动时返回无效统计，让上层报 unavailable —— 绝不返回全零的"健康"值。
    // 全零 FrameStats 的 frameLossRatio() 是 0.0，会被误读成"零丢帧"，这正是
    // 本项目反复强调"缺数据不得伪造 0"的同一个陷阱。
    if (!impl_->started) return out;

    const double frame_interval_ms = 1000.0 / static_cast<double>(impl_->fps);
    const uint64_t nominal_frames = static_cast<uint64_t>(
        static_cast<double>(impl_->window_ms) / frame_interval_ms);

    const uint64_t w = impl_->window;
    uint64_t received = nominal_frames;
    uint64_t expected = nominal_frames;
    uint32_t gap_events = 0;

    std::vector<uint32_t> gaps;
    gaps.reserve(static_cast<size_t>(nominal_frames));

    switch (impl_->pattern) {
        case SyntheticPattern::HEALTHY: {
            // 帧间隔恒等于标称值，无抖动
            const uint32_t g = static_cast<uint32_t>(frame_interval_ms);
            for (uint64_t i = 0; i < nominal_frames; ++i) gaps.push_back(g);
            break;
        }

        case SyntheticPattern::PERIODIC_LOSS: {
            // 每 30 帧丢 2 帧（约 6.7%），持续存在。
            // 表现是"画面一直在轻微断续"——丢帧量不大但发生频繁。
            constexpr uint64_t kPeriod = 30;
            constexpr uint64_t kDrop = 2;
            for (uint64_t i = 0; i < nominal_frames; ++i) {
                const uint64_t pos = (w * nominal_frames + i) % kPeriod;
                if (pos < kDrop) {
                    ++gap_events;
                    continue;
                }
                gaps.push_back(static_cast<uint32_t>(frame_interval_ms));
            }
            received = nominal_frames > gap_events ? nominal_frames - gap_events : 0;
            break;
        }

        case SyntheticPattern::BURST_LOSS: {
            // 偶数窗口正常、奇数窗口丢 30%：
            // 模拟"长时间正常后突然连续丢帧"，用户感知是卡住而非断续。
            // 注意丢的是连续一段而不是散点，所以 gap_events 只记 1 次
            // ——一次断流无论丢多少帧，都是一次"中断事件"。
            const bool burst = (w % 2) == 1;
            const uint64_t drop = burst ? (nominal_frames * 3 / 10) : 0;
            const uint64_t keep = nominal_frames - drop;
            for (uint64_t i = 0; i < keep; ++i) {
                gaps.push_back(static_cast<uint32_t>(frame_interval_ms));
            }
            if (burst && drop > 0) {
                gap_events = 1;
                // 断流期间有一个明显拉长的间隔：drop 帧本该占用的时间
                gaps.push_back(static_cast<uint32_t>(
                    frame_interval_ms * static_cast<double>(drop + 1)));
            }
            received = keep;
            break;
        }

        case SyntheticPattern::REORDERED: {
            // 全部到达，只是顺序错乱。**seq_gap_count 保持 0**。
            // 间隔仍然正常（乱序是顺序问题，不是时间问题）。
            const uint32_t g = static_cast<uint32_t>(frame_interval_ms);
            for (uint64_t i = 0; i < nominal_frames; ++i) gaps.push_back(g);
            received = nominal_frames;
            break;
        }
    }

    // 累计字节：乱序模式下按全部帧算（帧确实都到了）
    out.frames_expected = expected;
    out.frames_received = received;
    out.frames_corrupt = 0;   // 合成源不产生坏帧；真机源才需要从驱动标志推导
    out.seq_gap_count = gap_events;
    out.bytes_received = received * kSyntheticFrameBytes;

    if (!gaps.empty()) {
        out.max_gap_ms = *std::max_element(gaps.begin(), gaps.end());
        out.p95_gap_ms = percentile95(gaps);
    }

    out.sampled_at = std::chrono::steady_clock::now();

    // 推进时间线：窗口 +1，seq 跳到下一窗口的起点（缺口已在上面的 gap_events 记账）
    impl_->window += 1;
    impl_->next_seq += nominal_frames;

    return out;
}

std::string SyntheticFrameSource::describe() const {
    const char* pattern_name = "HEALTHY";
    switch (impl_->pattern) {
        case SyntheticPattern::HEALTHY:      pattern_name = "HEALTHY"; break;
        case SyntheticPattern::PERIODIC_LOSS: pattern_name = "PERIODIC_LOSS"; break;
        case SyntheticPattern::BURST_LOSS:   pattern_name = "BURST_LOSS"; break;
        case SyntheticPattern::REORDERED:    pattern_name = "REORDERED"; break;
    }
    std::ostringstream os;
    // 前缀 synthetic: 让 evidence 消费者能一眼区分"注入的测试数据"与真机观测
    os << "synthetic:" << pattern_name << "@" << impl_->fps << "fps/"
       << impl_->window_ms << "ms";
    return os.str();
}

uint64_t SyntheticFrameSource::windowCount() const { return impl_->window; }

uint64_t SyntheticFrameSource::nextSeq() const { return impl_->next_seq; }

}  // namespace weaknet

/**
 * @file frame_source.hpp
 * @brief 帧源抽象与帧统计（视频 QoE 的 L2/L3 层，零硬件可实现）
 *
 * 为什么要有这层抽象（而不是直接调 V4L2）：
 *
 *   视频质量判定需要两类完全不同的东西——「帧到底有没有按时到」和
 *   「为什么没到」。前者必须在真机上采，后者是纯推理。如果把两者
 *   焊死在一起，摄像头没到货就一行代码都写不了，摄像头到了又只能
 *   在真机上调试推理逻辑。
 *
 *   所以按 驱动面方案 §6.2.1 把两者切开：
 *
 *     L4  VideoQoeAttribution   ← 纯函数，只吃 FrameStats
 *     L3  FrameStats            ← 本文件定义的数据契约
 *     L2  IFrameSource          ← 本文件定义的接口（唯一分界线）
 *         ├─ SyntheticFrameSource   合成源，无硬件即可测透 L3/L4
 *         └─ V4l2FrameSource        真机源，待摄像头到货
 *     L1  内核 vind / csi / isp / sensor
 *
 *   IFrameSource 是唯一的分界线。它的契约稳定之后，换实现（合成→真机）
 *   不需要改动任何上层代码。
 *
 * 重要语义边界（不要越过）：
 *   FrameStats 是**原始事实**，不是结论。丢帧不等于网络故障，卡顿不等于
 *   链路劣化。它只能说明「这一路视频在采集端表现如何」，成因判定是
 *   VideoQoeAttribution 的职责，两者不可混淆。
 *
 *   同理，帧统计**不能**修改 OverallPolicy 的判决——它只产出归因。
 */

#pragma once

#include <chrono>
#include <cstdint>
#include <memory>
#include <string>

namespace weaknet {

/**
 * @brief 一个采样周期内的帧级统计（原始事实）
 *
 * 字段刻意只保留能从帧序号与到达时刻推导出来的量，不含任何「结论」。
 * 特别地：**没有 healthy / degraded 这类布尔字段**——那属于归因层。
 *
 * 时间语义：所有 *gap* 字段使用 std::chrono::steady_clock，不受系统
 * 时间跳变影响。这不是可选项：本项目的目标场景是工业现场，NTP 跳变
 * 会把 wall clock 差值直接变成几十年的假间隔。
 */
struct FrameStats {
    /// 按帧率推算「本周期应该到多少帧」
    ///
    /// 为什么需要它而不是直接用 frames_received：没有期望值就无法算丢帧率。
    /// 合成源可以精确给出；真机源需要从 V4L2 的 timeperframe 或配置推导。
    uint64_t frames_expected = 0;

    /// 实际收到的帧数
    uint64_t frames_received = 0;

    /// 序号不连续但内容可用的帧数（如驱动重排、丢帧后补齐）
    uint64_t frames_corrupt = 0;

    /// 序号跳变次数（≈ 丢帧次数，按「事件」计而非按「帧」计）
    ///
    /// 与 frames_expected - frames_received 的区别：后者是丢帧总量，
    /// 前者是丢帧发生的**次数**。一次丢 30 帧和三十次各丢 1 帧，
    /// 总量相同但 QoE 天差地别——前者是拔线，后者是拥塞。
    uint32_t seq_gap_count = 0;

    /// 最长帧间隔（毫秒）
    uint32_t max_gap_ms = 0;

    /// 帧间隔 P95（毫秒）——用于判断「整体卡顿」而非「偶发尖刺」
    uint32_t p95_gap_ms = 0;

    /// 本周期收到的总字节数（用于推算实际码率）
    uint64_t bytes_received = 0;

    /// 采样时刻。默认构造表示「从未采样」
    std::chrono::steady_clock::time_point sampled_at;

    /// 是否是一份有效采样
    ///
    /// 语义边界：valid()==false 时上层**必须**报 unavailable，
    /// 绝不能把全零字段当成「零丢帧、零延迟」——那是把「不知道」
    /// 伪装成「很好」，比缺数据更危险。
    bool valid() const {
        return sampled_at != std::chrono::steady_clock::time_point{};
    }

    /// 本周期丢帧数（不足 0 时钳到 0，防止期望值配置错误导致负数）
    uint64_t framesLost() const {
        return frames_expected > frames_received ? frames_expected - frames_received : 0;
    }

    /// 本周期丢帧率（0.0 ~ 1.0）。期望为 0 时返回 0，不产生 NaN
    double frameLossRatio() const {
        if (frames_expected == 0) return 0.0;
        return static_cast<double>(framesLost()) / static_cast<double>(frames_expected);
    }
};

/**
 * @brief 帧源接口（L2 层，唯一的分界线）
 *
 * 生命周期约定：
 *   start() → [ snapshotAndReset() ... ] → stop()
 *
 *   snapshotAndReset() 是「取走并清零」语义，不是「读取当前值」。
 *   这样每个统计窗口互不重叠，避免多次调用拿到重复数据导致丢帧率被
 *   重复计算。真机实现内部需要维护两个计数器（一个累计、一个上次快照），
 *   合成实现在推进时间线后直接返回增量。
 *
 * 线程约定：
 *   实现**不要求**线程安全。调用方（插件）单线程轮询即可，
 *   这也避免了在接口层引入锁的开销与死锁面。
 */
class IFrameSource {
public:
    virtual ~IFrameSource() = default;

    /// 开始采集。返回 false 表示无法启动（设备不存在、权限不足等）。
    ///
    /// 语义边界：start() 失败**不是**错误状态，是"这个能力不可用"。
    /// 上层应报 unavailable 并让业务链路照常运行，不得中断采集服务。
    virtual bool start() = 0;

    /// 停止采集。必须可重入（未 start 时调用不得崩溃）。
    virtual void stop() = 0;

    /// 取走本周期的统计并清零。无数据时返回 valid()==false 的 FrameStats。
    virtual FrameStats snapshotAndReset() = 0;

    /// 人类可读的来源描述，用于 evidence 溯源。
    ///
    /// 为什么要它：同一个 FrameStats 可能来自合成源或真机源，若不标明来源，
    /// 事后无法区分「这条证据是真的观测」还是「注入的测试数据」。
    /// 这是本项目 evidence 纪律的一部分。
    virtual std::string describe() const = 0;
};

/// 合成源的丢帧模式（用于在无硬件时覆盖全部 QoE 分支）
enum class SyntheticPattern {
    /// 正常：按标称帧率稳定出帧，无丢帧、无抖动
    HEALTHY,

    /// 周期性丢帧：每隔 N 帧丢一批，模拟稳定的网络拥塞
    ///
    /// 典型现场：无线链路带宽刚好不够，编码器超时后周期性放弃。
    PERIODIC_LOSS,

    /// 突发丢帧：长时间正常后突然连续丢帧，模拟链路瞬断
    ///
    /// 与 PERIODIC_LOSS 的区别在于 QoE 含义：一次丢 30 帧的用户感知
    /// 是「画面卡住了」，而周期性每次丢 1 帧是「画面一直在轻微断续」。
    BURST_LOSS,

    /// 乱序：帧都到了但顺序错乱（驱动重排 / 多路径）
    ///
    /// 关键语义：**乱序不是丢帧**。若实现把乱序计入 seq_gap，会让
    /// 归因层把「驱动行为」误判成「网络故障」，这是本模式存在的意义。
    REORDERED,
};

/**
 * @brief 合成帧源（无硬件即可验证整条 L3/L4 链路）
 *
 * 时间驱动而非真实计时：构造时给定帧率与采样周期，每次
 * snapshotAndReset() 推进一个窗口并直接算出本该发生的统计。
 *
 * 为什么不 sleep：sleep 会让单测变慢且不确定（CI 上尤其明显）。
 * 本实现把"时间"当作纯函数参数，同一组参数永远得到同一份 FrameStats，
 * 这正是纯函数可测性的价值。真机源才需要真实时钟。
 */
class SyntheticFrameSource : public IFrameSource {
public:
    /// @param pattern   丢帧模式
    /// @param fps       标称帧率（必须 > 0）
    /// @param window_ms 每个统计窗口的时长（必须 > 0）
    explicit SyntheticFrameSource(SyntheticPattern pattern = SyntheticPattern::HEALTHY,
                                  uint32_t fps = 30,
                                  uint32_t window_ms = 1000);

    bool start() override;
    void stop() override;
    FrameStats snapshotAndReset() override;
    std::string describe() const override;

    /// 已推进的窗口数（测试用：确认真的在推进而不是返回常量）
    uint64_t windowCount() const;

    /// 帧序号（测试用：真机源的 seq 来自驱动，合成源需要自己维护）
    uint64_t nextSeq() const;

private:
    struct Impl;
    std::unique_ptr<Impl> impl_;
};

}  // namespace weaknet

