25	namespace {
26	
27	std::string fmtMs(uint32_t v) {
28	    return std::to_string(v) + "ms";
29	}
30	
31	/// 画面侧的具体劣化项（唯一阈值判定处）
32	///
33	/// `isFrameQualityBad` 由它派生，绝不另写一份 —— 两份阈值实现迟早会漂移，
34	/// 届时「是否判为差」与「差的具体成因」会互相矛盾。
35	///
36	/// 放在匿名命名空间是因为它只服务于本文件的判定表；对外暴露会让调用方
37	/// 误以为可以绕过 attributeVideoQoe 单独取成因，而那会丢掉窗口对齐检查。
38	std::vector<std::string> collectFrameIssues(const FrameStats& frames,
39	                                            const VideoQoeThresholds& thresholds) {
40	    std::vector<std::string> issues;
41	
42	    // 无效统计一律视为「不知道」，不产生任何结论。
43	    // 这里返回空表示「没有明确地差」，由调用方决定怎么呈现 unavailable。
44	    if (!frames.valid()) return issues;
45	
46	    if (frames.frameLossRatio() >= thresholds.frame_loss_ratio_bad) {
47	        issues.emplace_back("FRAME_LOSS");
48	    }
49	
50	    if (frames.p95_gap_ms >= thresholds.frame_gap_p95_bad_ms) {
51	        issues.emplace_back("FRAME_GAP_P95");
52	    }
53	
54	    if (frames.frames_expected > 0) {
55	        const double corrupt_ratio =
56	            static_cast<double>(frames.frames_corrupt) /
57	            static_cast<double>(frames.frames_expected);
58	        if (corrupt_ratio >= thresholds.frame_corrupt_ratio_bad) {
59	            issues.emplace_back("CORRUPT_FRAMES");
60	        }
61	    }
62	
63	    return issues;
64	}
65	
66	}  // namespace
