68	bool isFrameQualityBad(const FrameStats& frames,
69	                       const VideoQoeThresholds& thresholds) {
70	    // 注意：无效统计一律视为「不知道」，由调用方决定怎么呈现。
71	    // 这里返回 false 是为了让 isFrameQualityBad 只回答「是否明确地差」，
72	    // 而不是把「不知道」也算进「差」——否则上游会把 unavailable 报成故障。
73	    return !collectFrameIssues(frames, thresholds).empty();
74	}
75	
76	VideoQoeAttributionResult attributeVideoQoe(
77	    const FrameStats& frames,
78	    const VideoNetworkObservation& network,
79	    const VideoQoeThresholds& thresholds) {
80	    VideoQoeAttributionResult result;
81	
82	    // ---- 前置检查 1：帧统计缺失 ----
83	    //
84	    // 这是最重要的一条纪律：无摄像头时归因必须是 NONE，绝不能因为
85	    // frames_expected==0 导致丢帧率算出 0.0 就报 CONSISTENT_HEALTHY。
86	    // 「不知道」伪装成「一切正常」比缺数据更危险。
87	    if (!frames.valid()) {
88	        result.attribution = VideoQoeAttribution::NONE;
89	        result.evaluated = false;
90	        result.reason = "frames_unavailable";
91	        result.explanation =
92	            "帧统计不可用（无摄像头 / 未启动 / 未采样），无法做视频 QoE 归因";
93	        return result;
94	    }
95	
96	    // ---- 前置检查 2：时间窗对齐 ----
97	    //
98	    // 方案 §6.2.4 纪律：帧统计与网络指标的时间窗必须对齐，否则四象限会误判。
99	    // 这里选择**拒绝归因**而不是尝试近似对齐：一个 200ms 的帧窗口配 5s 的
100	    // 网络窗口，"画面差但网络好"完全可能是窗口错位造成的假象。
101	    //
102	    // 两侧任一方未声明窗口时长都拒绝归因：把「没填」当成「一致」正是
103	    // 方案里点名要避免的误判来源。
104	    if (frames.window_ms == 0 || network.interval_ms == 0) {
105	        result.attribution = VideoQoeAttribution::NONE;
106	        result.evaluated = false;
107	        result.frames_bad = isFrameQualityBad(frames, thresholds);
108	        result.reason = "window_length_undeclared";
109	        result.explanation =
110	            "帧统计或网络侧未声明统计窗口时长（frames.window_ms=" +
111	            std::to_string(frames.window_ms) + ", network.interval_ms=" +
112	            std::to_string(network.interval_ms) +
113	            "），无法确认两路证据同窗，拒绝归因";
114	        return result;
115	    }
116	    if (frames.window_ms != network.interval_ms) {
117	        result.attribution = VideoQoeAttribution::NONE;
118	        result.evaluated = false;
119	        result.frames_bad = isFrameQualityBad(frames, thresholds);
120	        result.reason = "window_mismatch";
121	        result.explanation =
122	            "帧窗口 " + std::to_string(frames.window_ms) + "ms 与网络窗口 " +
123	            std::to_string(network.interval_ms) +
124	            "ms 不一致，四象限在错位窗口下必然误判，拒绝归因";
125	        return result;
126	    }
127	
128	    // ---- 前置检查 3：网络指标不可用 ----
129	    if (!network.available) {
130	        result.attribution = VideoQoeAttribution::NONE;
131	        result.evaluated = false;
132	        result.frames_bad = isFrameQualityBad(frames, thresholds);
133	        result.reason = "network_unavailable";
134	        result.explanation =
135	            "网络侧指标不可用，无法做双向校验（只有画面一路证据时不做链路归因）";
136	        return result;
137	    }
138	
139	    // ================= 五行真值表 =================
140	    //
141	    // 成因清单只在这里填：四条拒绝归因的路径都提前 return 了，issues 保持
142	    // 默认空 —— 「没采到帧」不得编造成因，与「没采到帧」不得报健康同理。
143	    //
144	    // frames_bad 直接由清单派生，不再单独调 isFrameQualityBad：两处各算一遍
145	    // 没有问题，但让「是否判为差」与「差在哪」共用同一次判定，将来加阈值
146	    // 时不可能只改一边。
147	    result.issues = collectFrameIssues(frames, thresholds);
148	    const bool frames_bad = !result.issues.empty();
149	    const bool network_bad = network.degraded;
150	    result.frames_bad = frames_bad;
151	    result.evaluated = true;
152	
153	    // 证据：画面侧原始事实。数值原样保留，不做任何「修匀」。
154	    result.evidence.push_back(EvidenceItem{
155	        "video_frame_loss_ratio", frames.frameLossRatio(),
156	        "lost=" + std::to_string(frames.framesLost()) + "/" +
157	            std::to_string(frames.frames_expected)});
158	    result.evidence.push_back(
159	        EvidenceItem{"video_frame_gap_p95_ms", static_cast<double>(frames.p95_gap_ms),
160	                     "max=" + fmtMs(frames.max_gap_ms)});
161	    result.evidence.push_back(
162	        EvidenceItem{"video_seq_gap_count", static_cast<double>(frames.seq_gap_count),
163	                     "gap events, not lost frames"});
164	
165	    // ---- 画面好 + 网络好 ----
166	    if (!frames_bad && !network_bad) {
167	        result.attribution = VideoQoeAttribution::CONSISTENT_HEALTHY;
168	        result.reason = "frames_good_network_good";
169	        result.explanation = "画面与网络侧指标一致地正常";
170	        return result;
171	    }
172	
173	    // ---- 画面差 + 网络好 ----
174	    if (frames_bad && !network_bad) {
175	        result.attribution = VideoQoeAttribution::APP_LAYER_SUSPECT;
176	        result.reason = "frames_bad_network_good";
177	        result.explanation =
178	            "画面劣化但网络侧指标正常，问题在应用侧或采集侧"
179	            "（编码器 / 内存 / CPU / sensor / ISP），不是链路";
180	        return result;
181	    }
182	
183	    // ---- 画面好 + 网络差（反向校验）----
184	    //
185	    // 这是本设计最锋利的一条：不给网络开脱，而是指向我们自己。
186	    // 画面完全正常而协议栈说网络很差，最可能的解释是观测方法本身有问题
187	    // （采样过密、探针冲突、观测者过载）。
188	    if (!frames_bad && network_bad) {
189	        result.attribution = VideoQoeAttribution::NETWORK_UNVERIFIED;
190	        result.reason = "frames_good_network_bad";
191	        result.explanation =
192	            "网络侧指标劣化但画面正常，反向校验失败：高度怀疑观测方法本身有问题"
193	            "（采样过密 / 探针冲突 / 观测者过载），应转查 CPU 与 thermal 归因";
194	        return result;
195	    }
196	
197	    // ---- 画面差 + 网络差：按持续性分裂 ----
198	    //
199	    // 一次丢帧就说链路坏了，会让现场人员去查一条其实没问题的线。
200	    // 持续多窗口才升级为高置信。
201	    if (network.consecutive_degraded_windows >= thresholds.confirm_windows) {
202	        result.attribution = VideoQoeAttribution::CONFIRMED_LINK_FAULT;
203	        result.reason = "frames_bad_network_bad_sustained";
204	        result.explanation =
205	            "画面与网络侧指标同时劣化且已持续 " +
206	            std::to_string(network.consecutive_degraded_windows) + " 个窗口（阈值 " +
207	            std::to_string(thresholds.confirm_windows) + "），双重确认的链路故障";
208	        return result;
209	    }
210	
211	    // 到这里必然是「画面差 + 网络差 + 未持续」
212	    result.attribution = VideoQoeAttribution::NETWORK_TRANSIENT;
213	    result.reason = "frames_bad_network_bad_transient";
214	    result.explanation =
215	        "画面与网络侧指标同时劣化，但仅持续 " +
216	        std::to_string(network.consecutive_degraded_windows) + " 个窗口（阈值 " +
217	        std::to_string(thresholds.confirm_windows) + "），先观察不急于定性";
218	    return result;
219	}
220	
221	}  // namespace weaknet
