15	 * 3. **P95 用排序取位而非近似**：窗口内帧数在几百量级，全排序的成本可以
16	 *    忽略，而近似算法（如直方图分桶）会引入桶宽误差，让 1ms 级的抖动
17	 *    判定失真。宁可简单准确，也不做没必要的优化。
18	 */
19	
20	#include "frame_source.hpp"
21	
22	#include <algorithm>
23	#include <cmath>
24	#include <cstdlib>
25	#include <sstream>
26	#include <vector>
27	
28	namespace weaknet {
29	
30	namespace {
31	
32	/// 合成帧的假定帧大小（未压缩的 NV12 近似值，仅用于让 bytes_received 非零）
33	constexpr uint64_t kSyntheticFrameBytes = 640u * 480u * 3u / 2u;
34	
35	/**
36	 * @brief 计算 P95（最近秩法）
37	 *
38	 * 空容器返回 0。取 ceil(0.95 * n) - 1 下标，n=20 时取第 19 个（0-based 18），
39	 * 语义是「95% 的样本不超过该值」，与本项目其它 P95 用法一致。
40	 */
41	uint32_t percentile95(std::vector<uint32_t> values) {
42	    if (values.empty()) return 0;
43	    std::sort(values.begin(), values.end());
44	    const size_t idx = static_cast<size_t>(
45	        std::ceil(0.95 * static_cast<double>(values.size())) - 1.0);
46	    return values[std::min(idx, values.size() - 1)];
47	}
48	
49	}  // namespace
50	
51	struct SyntheticFrameSource::Impl {
52	    SyntheticPattern pattern;
53	    uint32_t fps;
54	    uint32_t window_ms;
55	
56	    bool started = false;
57	    uint64_t window = 0;      ///< 已推进的窗口数
58	    uint64_t next_seq = 0;    ///< 下一个帧序号
59	
60	    Impl(SyntheticPattern p, uint32_t f, uint32_t w)
61	        : pattern(p), fps(f ? f : 30), window_ms(w ? w : 1000) {}
62	};
63	
64	SyntheticFrameSource::SyntheticFrameSource(SyntheticPattern pattern, uint32_t fps,
65	                                           uint32_t window_ms)
66	    : impl_(std::make_unique<Impl>(pattern, fps, window_ms)) {}
67	
68	SyntheticFrameSource::~SyntheticFrameSource() = default;
69	
70	bool SyntheticFrameSource::start() {
71	    impl_->started = true;
72	    impl_->window = 0;
73	    impl_->next_seq = 0;
74	    return true;
75	}
76	
77	void SyntheticFrameSource::stop() {
78	    // 幂等：未 start 时调用不做事，也不改动计数
79	    impl_->started = false;
80	}
81	
82	FrameStats SyntheticFrameSource::snapshotAndReset() {
83	    FrameStats out;
84	
85	    // 未启动时返回无效统计，让上层报 unavailable —— 绝不返回全零的"健康"值。
86	    // 全零 FrameStats 的 frameLossRatio() 是 0.0，会被误读成"零丢帧"，这正是
87	    // 本项目反复强调"缺数据不得伪造 0"的同一个陷阱。
88	    if (!impl_->started) return out;
89	
90	    const double frame_interval_ms = 1000.0 / static_cast<double>(impl_->fps);
91	    // 帧数必须用整数运算并四舍五入，**不能**写成 window_ms / frame_interval_ms
92	    // 再截断：1000.0 / (1000.0/30) 在 IEEE-754 下是 29.999999999999996，
93	    // 截断后变成 29 帧，丢帧率因此长期偏移约 3%，且分母错误会让所有
94	    // 阈值判定系统性偏松。整数形式没有这个问题，且对任意 fps 都精确。
95	    const uint64_t nominal_frames =
96	        (static_cast<uint64_t>(impl_->window_ms) * impl_->fps + 500u) / 1000u;
97	
98	    const uint64_t w = impl_->window;
99	    uint64_t received = nominal_frames;
100	    uint64_t expected = nominal_frames;
101	    uint32_t gap_events = 0;
102	
103	    std::vector<uint32_t> gaps;
104	    gaps.reserve(static_cast<size_t>(nominal_frames));
105	
106	    switch (impl_->pattern) {
107	        case SyntheticPattern::HEALTHY: {
108	            // 帧间隔恒等于标称值，无抖动
109	            const uint32_t g = static_cast<uint32_t>(frame_interval_ms);
110	            for (uint64_t i = 0; i < nominal_frames; ++i) gaps.push_back(g);
111	            break;
112	        }
113	
114	        case SyntheticPattern::PERIODIC_LOSS: {
115	            // 每 30 帧丢 2 帧（约 6.7%），持续存在。
116	            // 表现是"画面一直在轻微断续"——丢帧量不大但发生频繁。
117	            constexpr uint64_t kPeriod = 30;
118	            constexpr uint64_t kDrop = 2;
119	            for (uint64_t i = 0; i < nominal_frames; ++i) {
120	                const uint64_t pos = (w * nominal_frames + i) % kPeriod;
121	                if (pos < kDrop) {
122	                    ++gap_events;
123	                    continue;
124	                }
125	                gaps.push_back(static_cast<uint32_t>(frame_interval_ms));
126	            }
127	            received = nominal_frames > gap_events ? nominal_frames - gap_events : 0;
128	            break;
129	        }
130	
131	        case SyntheticPattern::BURST_LOSS: {
132	            // 偶数窗口正常、奇数窗口丢 30%：
133	            // 模拟"长时间正常后突然连续丢帧"，用户感知是卡住而非断续。
134	            // 注意丢的是连续一段而不是散点，所以 gap_events 只记 1 次
135	            // ——一次断流无论丢多少帧，都是一次"中断事件"。
136	            const bool burst = (w % 2) == 1;
137	            const uint64_t drop = burst ? (nominal_frames * 3 / 10) : 0;
138	            const uint64_t keep = nominal_frames - drop;
139	            for (uint64_t i = 0; i < keep; ++i) {
140	                gaps.push_back(static_cast<uint32_t>(frame_interval_ms));
141	            }
142	            if (burst && drop > 0) {
143	                gap_events = 1;
144	                // 断流期间有一个明显拉长的间隔：drop 帧本该占用的时间
145	                gaps.push_back(static_cast<uint32_t>(
146	                    frame_interval_ms * static_cast<double>(drop + 1)));
147	            }
148	            received = keep;
149	            break;
150	        }
151	
152	        case SyntheticPattern::REORDERED: {
153	            // 全部到达，只是顺序错乱。**seq_gap_count 保持 0**。
154	            // 间隔仍然正常（乱序是顺序问题，不是时间问题）。
155	            const uint32_t g = static_cast<uint32_t>(frame_interval_ms);
156	            for (uint64_t i = 0; i < nominal_frames; ++i) gaps.push_back(g);
157	            received = nominal_frames;
158	            break;
159	        }
160	    }
161	
162	    // 累计字节：乱序模式下按全部帧算（帧确实都到了）
163	    out.frames_expected = expected;
164	    out.frames_received = received;
165	    out.frames_corrupt = 0;   // 合成源不产生坏帧；真机源才需要从驱动标志推导
166	    out.seq_gap_count = gap_events;
167	    out.bytes_received = received * kSyntheticFrameBytes;
168	    // 窗口时长随统计一起给出，让归因层能真正校验与网络侧是否同窗
169	    out.window_ms = impl_->window_ms;
170	
171	    if (!gaps.empty()) {
172	        out.max_gap_ms = *std::max_element(gaps.begin(), gaps.end());
173	        out.p95_gap_ms = percentile95(gaps);
174	    }
175	
176	    out.sampled_at = std::chrono::steady_clock::now();
177	
178	    // 推进时间线：窗口 +1，seq 跳到下一窗口的起点（缺口已在上面的 gap_events 记账）
179	    impl_->window += 1;
180	    impl_->next_seq += nominal_frames;
181	
182	    return out;
183	}
184	
185	std::string SyntheticFrameSource::describe() const {
186	    const char* pattern_name = "HEALTHY";
187	    switch (impl_->pattern) {
188	        case SyntheticPattern::HEALTHY:      pattern_name = "HEALTHY"; break;
189	        case SyntheticPattern::PERIODIC_LOSS: pattern_name = "PERIODIC_LOSS"; break;
190	        case SyntheticPattern::BURST_LOSS:   pattern_name = "BURST_LOSS"; break;
191	        case SyntheticPattern::REORDERED:    pattern_name = "REORDERED"; break;
192	    }
193	    std::ostringstream os;
194	    // 前缀 synthetic: 让 evidence 消费者能一眼区分"注入的测试数据"与真机观测
195	    os << "synthetic:" << pattern_name << "@" << impl_->fps << "fps/"
196	       << impl_->window_ms << "ms";
197	    return os.str();
198	}
199	
200	uint64_t SyntheticFrameSource::windowCount() const { return impl_->window; }
201	
202	uint64_t SyntheticFrameSource::nextSeq() const { return impl_->next_seq; }
203	
204	}  // namespace weaknet
